-- 159_vm_manchete_2026_10_19.sql — Valor e Mercado: MANCHETE DE CAPA de segunda-feira, 19/10/2026, escrita pelo Thiago
-- Pedido do Thiago (18/10/2026 01h03): "gere essa notícia de capa para amanhã com foto do Donald Trump (editada com um fundo de
-- indústria do petróleo)". Texto do Thiago (números corrigidos e conferidos), intertítulos com "## " (site v134), fotomontagem
-- própria sobre duas fotos de DOMÍNIO PÚBLICO (retrato oficial da Casa Branca, Daniel Torok; refinaria da Valero em Port Arthur,
-- Carol M. Highsmith/Biblioteca do Congresso), marcada "FOTOMONTAGEM" e hospedada no próprio site (pasta noticias/img da v134).
-- Como funciona: a edição de 19/10 entra AGORA como NÃO publicada (não aparece no site hoje). Um agendamento único publica às
-- 04h50 de 19/10 — antes de o robô da manchete começar (05h00): ao ver a edição publicada, ele não escreve outra.
-- Rodar no SQL Editor (Supabase > SQL Editor > New query > Run). Não mexe no Scanner.

insert into public.vm_edicoes (data, conteudo, fontes, modelo, custo_usd, gerado_em, publicado)
values ('2026-10-19', $manchete${"manchete": {"cartola": "ANÁLISE · PETRÓLEO E GEOPOLÍTICA", "titulo": "O petróleo como instrumento de poder", "linha_fina": "A estratégia trumpista de captura de renda e a adaptação da Doutrina Monroe: por que o barril não dá sinais de voltar à média histórica", "corpo": ["A política energética da administração Trump não é reativa nem acidental. Ela expressa uma preferência deliberada por cotações elevadas do petróleo, que transferem renda massiva para a indústria que financiou sua campanha e acumulam capital para que esse mesmo setor lidere — e não sofra — a transição energética. Essa estratégia constitui a adaptação trumpista da Doutrina Monroe, na qual o controle de recursos estratégicos se torna o eixo da projeção de poder dos Estados Unidos.", "## O financiamento e o pedido explícito", "Em abril de 2024, em um jantar no Mar-a-Lago com cerca de vinte executivos de petróleo e gás — incluindo representantes de Exxon Mobil, Chevron, ConocoPhillips, Continental Resources, EQT e do American Petroleum Institute —, Trump pediu que o setor levantasse US$ 1 bilhão para sua campanha de retorno à Casa Branca, prometendo em troca a reversão de regulamentações ambientais e benefícios fiscais.", "A indústria não entregou o US$ 1 bilhão solicitado. O que se verificou foi um gasto total do setor de petróleo e gás de US$ 249 milhões no ciclo eleitoral de 2024, segundo análise da OpenSecrets — um aumento de 66% em relação a 2020. Desse total, 88% foram direcionados a candidatos e causas republicanas. Em contribuições diretas à campanha presidencial, Trump recebeu US$ 2,6 milhões do setor, contra US$ 1,4 milhão de Kamala Harris. Além disso, mais de US$ 75 milhões foram canalizados para comitês de ação política (PACs) afiliados a Trump.", "A relação, portanto, não é de um \"retorno\" mecânico sobre um pedido específico, mas de alinhamento estrutural: o setor financiou majoritariamente o campo político que lhe oferecia desregulamentação e apoio à expansão fóssil.", "## A engenharia geopolítica da elevação de preços", "A administração Trump utilizou instrumentos de política externa para restringir a oferta global e sustentar cotações elevadas. A intervenção militar na Venezuela, em janeiro de 2026, seguida da sinalização de que os EUA supervisionariam a reconstrução da indústria petrolífera venezuelana, produziu ganhos imediatos para empresas americanas: as ações da Chevron subiram 5,1%, as da Exxon Mobil atingiram a máxima de 52 semanas, e as de prestadoras de serviços como SLB e Halliburton avançaram 8,9% e 7,8%, respectivamente.", "Trump foi explícito sobre a lógica: \"Vamos reconstruir a infraestrutura petrolífera, o que custará bilhões de dólares que serão pagos diretamente pelas petrolíferas. Elas serão reembolsadas pelo que estão fazendo, mas vai ser pago, e vamos fazer o petróleo fluir como deveria\". A fala revela o arranjo: a política externa cria as condições para que o capital privado americano capture ativos e fluxos de caixa em áreas de influência dos EUA.", "O setor de óleo de xisto (fracking), que só opera com margens confortáveis acima de determinado patamar de preço, é o beneficiário direto dessa arquitetura. O senador Sheldon Whitehouse resumiu o arranjo em março de 2026: \"Trump está aplaudindo as gigantes petrolíferas enquanto elas exploram eventos mundiais para acumular lucros massivos. Ele não se importa nem um pouco que você e sua família estejam pagando o preço\".", "## Acumulação de capital e a liderança da transição", "A tese de que os lucros extraordinários do petróleo financiariam a transição energética é conveniente para o setor, mas a alocação real de capital revela outra prioridade. O fluxo de caixa gerado pelos preços elevados é direcionado predominantemente ao núcleo fóssil — exploração, produção, refino e infraestrutura —, e apenas de forma marginal a renováveis ou tecnologias de baixo carbono.", "Isso não significa que a transição não ocorrerá. Significa que ela será liderada pelos mesmos agentes que sempre lucraram com o modelo fóssil, em um ritmo e com uma arquitetura tecnológica que preservem sua centralidade no sistema energético. A transição deixa de ser uma ruptura e se torna uma diversificação defensiva, financiada pela renda extraordinária extraída do próprio petróleo.", "## A \"Doutrina Donroe\" e o controle de ativos estratégicos", "A Estratégia de Segurança Nacional (National Security Strategy) divulgada em dezembro de 2025 explicitou essa lógica. O documento anuncia um \"Corolário Trump\" à Doutrina Monroe, segundo o qual os Estados Unidos têm o direito de \"reavivar\" a doutrina de 1823 e impedir que \"competidores não hemisféricos\" — leia-se China — possuam ou controlem \"ativos estrategicamente vitais\" no Hemisfério Ocidental. A estratégia afirma que o hemisfério deve ser controlado pelos EUA \"política, econômica, comercial e militarmente\", e que o país usará sua superioridade militar para \"obter acesso a recursos energéticos e minerais\" na região.", "Analistas têm chamado essa adaptação de \"Doutrina Donroe\" — uma fusão de \"Donald\" e \"Monroe\". Trata-se de uma versão da doutrina original que, em vez de apenas barrar potências europeias, busca subordinar a soberania sobre recursos e as cadeias globais de suprimento ao controle estratégico americano, onde quer que energia e poder se cruzem.", "## Um preço que não se acomoda", "Os dados de mercado confirmam que não há sinal de acomodação do petróleo à média histórica. Na sexta-feira, 16 de outubro, o Brent fechou a US$ 109,86 por barril e o WTI, a US$ 99,02 — o Brent acumula alta de cerca de 79% em doze meses. No relatório de curto prazo publicado em 6 de outubro (Short-Term Energy Outlook), a Administração de Informação de Energia dos EUA (EIA) projetou média de US$ 96,32 para o Brent e de US$ 88,21 para o WTI em 2026, com o Brent em torno de US$ 105 no quarto trimestre.", "Não se trata de volatilidade conjuntural. Trata-se de um patamar estruturalmente elevado, sustentado por uma política de Estado que usa a geopolítica para restringir a oferta, transferir renda para a indústria doméstica e converter essa renda em poder econômico e geopolítico. Enquanto essa arquitetura permanecer, o preço do petróleo não dará sinais de retorno à média histórica. E a transição energética, nesse arranjo, não será financiada contra o petróleo, mas pelo petróleo e para os mesmos agentes que sempre lucraram com ele."], "foto": {"id": "montagem-2026-10-19-petroleo-poder", "src": "https://soliduns.com.br/noticias/img/2026-10-19-petroleo-poder-1200.jpg", "src_grande": "https://soliduns.com.br/noticias/img/2026-10-19-petroleo-poder-1880.jpg", "alt": "Fotomontagem: Donald Trump diante de uma refinaria de petróleo ao entardecer", "fotografo": "Fotomontagem sobre fotos de Daniel Torok (Casa Branca) e Carol M. Highsmith (Biblioteca do Congresso dos EUA), domínio público", "fotografo_url": "https://commons.wikimedia.org/wiki/File:Official_Presidential_Portrait_of_President_Donald_J._Trump_(2025).jpg", "pagina_url": "https://commons.wikimedia.org/wiki/File:Dusk_view_of_the_Valero_Energy_Corporation%27s_refinery_in_Port_Arthur,_Texas_LCCN2014633835.tif", "fonte": "Wikimedia Commons", "busca": "fotomontagem", "cor_media": "#1b2335"}}, "scanner": {}}$manchete$::jsonb, $manchete$[{"titulo": "EIA — Short-Term Energy Outlook, outubro de 2026", "url": "https://www.eia.gov/outlooks/steo/archives/oct26.pdf"}, {"titulo": "Trading Economics — petróleo Brent e WTI", "url": "https://pt.tradingeconomics.com/commodity/crude-oil"}, {"titulo": "Yahoo Finance — Chevron e petroleiras sobem com a promessa de Trump de reerguer o petróleo venezuelano", "url": "https://finance.yahoo.com/news/chevron-oil-stocks-soar-trump-144333025.html"}, {"titulo": "Dallas Express — Trump e o reembolso das petroleiras na Venezuela", "url": "https://dallasexpress.com/national/trump-eyes-oil-company-reimbursements-for-reviving-venezuelas-oil-sector/"}]$manchete$::jsonb, 'redacao', 0,
        '2026-10-19 04:50:00-03', false)
on conflict (data) do update set conteudo = excluded.conteudo, fontes = excluded.fontes, modelo = excluded.modelo,
  custo_usd = excluded.custo_usd, gerado_em = excluded.gerado_em, publicado = false;

do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'vm-manchete-2026-10-19';
  perform cron.schedule('vm-manchete-2026-10-19', '50 7 19 10 *', $job$
    update public.vm_edicoes set publicado = true, gerado_em = now() where data = '2026-10-19';
    select cron.unschedule('vm-manchete-2026-10-19');
  $job$);
end $$;

-- conferência: esperado 1 linha "2026-10-19 | false | O petróleo como instrumento de poder | 18 | 50 7 19 10 *"
select e.data, e.publicado, e.conteudo->'manchete'->>'titulo' as titulo, jsonb_array_length(e.conteudo->'manchete'->'corpo') as blocos,
       (select schedule from cron.job where jobname = 'vm-manchete-2026-10-19') as agenda
  from public.vm_edicoes e where e.data = '2026-10-19';
